  '[Console]::OutputEncoding = [Text.Encoding]::UTF8',      // Windows PowerShell writes the console code page (850 on many PCs): an accented publisher would arrive broken
  'Add-Type -AssemblyName System.IO.Compression.FileSystem',
  "$tmp = Join-Path ([IO.Path]::GetTempPath()) ('agile-sign-' + [guid]::NewGuid())",
  'New-Item -ItemType Directory $tmp | Out-Null',
  'try {',
  '  $items = @(@{ file = (Split-Path $env:AGILE_SIGN_SETUP -Leaf); path = $env:AGILE_SIGN_SETUP })',
  '  $zip = [IO.Compression.ZipFile]::OpenRead($env:AGILE_SIGN_NUPKG)',
  '  try {',
  "    foreach ($n in @($env:AGILE_SIGN_EXE, 'Squirrel.exe')) {",
