  '  $out = foreach ($i in $items) {',
  "    if (-not $i.path) { [pscustomobject]@{ file = $i.file; status = 'NotInPackage'; subject = '' }; continue }",
  '    $s = Get-AuthenticodeSignature -LiteralPath $i.path',
  "    $subject = ''; if ($s.SignerCertificate) { $subject = $s.SignerCertificate.Subject }",
  '    [pscustomobject]@{ file = $i.file; status = [string]$s.Status; subject = $subject }',
  '  }',
  '  ConvertTo-Json -Compress -InputObject @($out)',
  '} finally { Remove-Item -Recurse -Force $tmp }',
