  if (insideProject(keystore)) return { reason: `${name}: the keystore is inside the repository (${SIGNING_VARS[0]}): keep it outside` };
  if (!fs.existsSync(keystore)) return { reason: `${name}: the keystore file named by ${SIGNING_VARS[0]} does not exist` };
  const bad = androidFileProblem(csproj);
