// Merge subjects since the previous tag (BR8). `Merge feature/F-3: text (0.0.9, #3)` -> Feature F-3.
function notesOf(version, previous, merges, { glossary = true } = {}) {
  const items = [], other = [];
  for (const subject of merges) {
    const m = /^Merge (?:remote-tracking )?(?:branch )?'?([^\s:']+)'?(?::\s*(.*))?$/.exec(subject);
    if (!m) { other.push(`- ${subject}`); continue; }
    const [, branch, text = ''] = m;
    const kind = /^feature\//.test(branch) ? 'Feature' : /^bug\//.test(branch) ? 'Bug' : null;
    const tail = branch.replace(/^(feature|bug)\//, '');
    (kind ? items : other).push(kind ? `- ${kind} ${tail}: ${text}`.trimEnd() : `- ${branch}: ${text}`.trimEnd());
  }
  const lines = [`# v${version}`, '', ...(glossary ? ['Technical terms: [glossary](../glossary.md)', ''] : []), previous ?`Since ${previous}.` : 'First release.', ''];
  if (!items.length && !other.length) lines.push('No merges on the main branch since then.', '');
  if (items.length) lines.push('## Items', '', ...items, '');
  if (other.length) lines.push('## Other', '', ...other, '');
  return { items: items.length, other: other.length, text: lines.join('\n') };
}

