  const command = unquote(row.cells[cCmd] || '');
  const checkUrl = cCheck >= 0 ? unquote(row.cells[cCheck] || '') : '';
  const url = cUrl >= 0 ? unquote(row.cells[cUrl] || '') : '';   // #76: the host of the URL of an aca environment is its custom domain
  const deployed = (/\bv\d+\.\d+\.\d+\S*/.exec(row.cells[cVer] || '') || [])[0] || null;
