    const bad = pipelineScript.cloudRowProblem(pipelineScript.cloudFor(text, environment).row);
    if (bad) return { ...result, stop: [bad] };
    const yml = read(path.join(project, VPS_WORKFLOW));
    if (yml === null) return { ...result, stop: [`${VPS_WORKFLOW} does not exist: run \`node sync.js pipeline vps write\` (the plugin's /agile:sync lists it); nothing ran`] };
