  const isAca = cloud.env && result.recipe && pipelineScript.deployTarget(project, command, environment).target === 'aca';
  if (withSpend && isAca) { const sp = await pipelineScript.readSpend(cloud.cloud.row, cloud.env); result.cloud.spendLine = sp.ok ? `Spend: ${sp.text}` : `Spend: not read (${sp.reason})`; }
  // #155: the plan reads what the Region can host; a proven shortage stops it, a failed read is said and never stops (BR3).
  if (withSpend && isAca) { const cap = pipelineScript.readCapacity(cloud.cloud.row, cloud.env, project, command, environment); if (cap.stop) return { ...result, stop: [cap.stop] }; result.cloud.capacityLine = cap.line; }
  // #75 BR8: the plan says when the deploy starts a parked environment's database first, and starts nothing.
