const CARGO_CODE = /(\.rs|(^|[\\/])Cargo\.(toml|lock))$/i;
const NPM_SKIP = /(^|[\\/])(node_modules|out)[\\/]/;   // generated or installed code of an npm project
const CARGO_SKIP = /(^|[\\/])target[\\/]/;            // the build folder of a crate; a .NET project has no skip folder (a `.cs` under out/ or target/ is its code)

const readJson = file => { try { const j = JSON.parse(fs.readFileSync(file, 'utf8')); return j && typeof j === 'object' ? j : {}; } catch { return {}; } };
const overrides = root => {
  const b = readJson(path.join(root, '.claude', 'agile', 'build.json'));
  const text = k => (typeof b[k] === 'string' && b[k].trim() ? b[k].trim() : '');
  return { build: text('buildCommand'), test: text('testCommand') };
};
