    native: true,                                       // gate.js runs the commands below itself
    baseline: false,                                    // no warnings baseline is kept for this engine
    projectFile: 'package.json',
    // A fresh worktree has no node_modules (ignored): a project that declares dependencies needs `npm ci` before any command can run.
    needsInstall: root => { const p = readJson(path.join(root, 'package.json')); return !has(root, 'node_modules') && ['dependencies', 'devDependencies'].some(k => p[k] && typeof p[k] === 'object' && Object.keys(p[k]).length > 0); },
    installDir: 'node_modules',
