  if (stage && !/^[0-9a-f]{40}$/.test(commit)) return stop(`"${commit}" is not a full commit id (AGILE_COMMIT)`);
  if (!stage && !/^v\d+\.\d+\.\d+\S*$/.test(tag)) return stop(`"${tag}" is not a tag like v0.3.0`);
