      const names = listing.stdout.split('\n').map(s => s.trim()).filter(Boolean);
      tables += names.length;
      if (!names.length) { lines.push(`database ${db}: no user tables`); continue; }
      const counted = psql(db, `set statement_timeout = '30s';\n${names.map((n, i) => `select '${i}|' || count(*) from ${n};`).join('\n')}\n`);
      const counts = {}, errors = {};
      for (const l of counted.stdout.split('\n')) { const m = /^(\d+)\|(\d+)$/.exec(l.trim()); if (m) counts[m[1]] = Number(m[2]); }
      // psql names the line of the script that failed: the first statement is on line 2 (line 1 sets the timeout).
      for (const l of counted.out.split('\n')) { const m = /:(\d+): ERROR:\s+(.*)$/.exec(l.trim()); if (m) errors[Number(m[1]) - 2] = m[2]; }
