    if (!ddb.ok) { out.reason = ddb.reason; return out; }
    const missing = sdb.names.filter(n => !ddb.names.includes(n));
    if (missing.length) diffs.push(`database${missing.length > 1 ? 's' : ''} ${missing.join(', ')} missing`);
    if (diffs.length) { out.reason = `the restored server differs from ${server.name}: ${diffs.join('; ')}`; return out; }
    out.shape.push(`shape: Ready, version ${b.version}, ${b.sku}, ${b.storageGb} GB; databases ${sdb.names.length ? sdb.names.join(', ') : 'none besides Azure\'s'}`);
    if (!withData) out.dataNote = 'psql not found on PATH';
    else if (!sdb.names.length) out.dataNote = `no application database on ${server.name}`;
